"""پالت رنگی برنامه در دو تم تیره و روشن.

تمام رنگ‌های رابط از اینجا می‌آید تا «فونت روشن روی کادر تیره» در تم تیره و
برعکسش در تم روشن، در همه صفحه‌ها یک‌دست بماند. هر نقش یک‌بار نام‌گذاری شده و
استایل فقط با نام نقش ساخته می‌شود؛ پس تغییر پالت هیچ‌وقت یک استایل را نیمه‌کاره
جای می‌گذارد. کنتراست جفت‌های متن/سطح با WCAG سنجیده شده است (تست پیکسلی همین
را قفل می‌کند): متن اصلی روی سطوح دست‌کم ۴٫۵:۱ و متن ثانویه بالای ۳:۱.
"""

from __future__ import annotations

import re

from PySide6.QtGui import QColor, QGuiApplication

DARK = "dark"
LIGHT = "light"
SYSTEM = "system"
THEMES = (DARK, LIGHT, SYSTEM)

DEFAULT_THEME = DARK

