LIGHT_PALETTE = {'window': '#f3f5f9', 'surfaceSubtle': '#e9edf3', 'surface': '#ffffff', 'mutedSurface': '#eef1f6', 'doneRow': '#eceff4', 'dangerHoverBg': '#f6e3e3', 'raised': '#ffffff', 'border': '#d4dbe5', 'borderStrong': '#b9c4d4', 'selected': '#d7dfeb', 'disabledSurface': '#e7ebf1', 'textBright': '#101623', 'textPrimary': '#1c2534', 'textBody': '#33405a', 'textSoft': '#4d5a72', 'textSecondary': '#5d6b84', 'textMuted': '#6d7a92', 'onAccent': '#ffffff', 'disabledText': '#9aa5b8', 'accent': '#3c58e8', 'accentHover': '#3450d6', 'accentPressed': '#2f47bd', 'accentSoft': '#4257c9', 'chipBg': '#f0f3f8', 'warningBg': '#fdf3e0', 'warningBorder': '#e4cf9d', 'warningHoverBg': '#faeccb', 'warningText': '#8a5c0a', 'successBg': '#e5f5ec', 'successBorder': '#a8d8bd', 'successText': '#1c6b45', 'dangerBg': '#fbe9ec', 'dangerBorder': '#dfa6b1', 'dangerText': '#a02135', 'dangerAccent': '#b3233a'}


def contrast_ratio(foreground: str, background: str) -> float:
    """نسبت کنتراست WCAG دو رنگ را برمی‌گرداند (برای تست پیکسلی و تنظیم پالت)."""

    def luminance(hex_color: str) -> float:
        color = QColor(hex_color)
        channels = [channel / 255 for channel in (color.red(), color.green(), color.blue())]
        linear = [
            channel / 12.92 if channel <= 0.04045 else ((channel + 0.055) / 1.055) ** 2.4
            for channel in channels
        ]
        return 0.2126 * linear[0] + 0.7152 * linear[1] + 0.0722 * linear[2]

    first, second = luminance(foreground), luminance(background)
    lighter, darker = max(first, second), min(first, second)
    return (lighter + 0.05) / (darker + 0.05)


def effective_theme(theme: str = DEFAULT_THEME) -> str:
    """تم واقعی را برای انتخاب دستی یا تم سیستم‌عامل برمی‌گرداند."""
    if theme in (DARK, LIGHT):
        return theme

    if theme == SYSTEM:
        application = QGuiApplication.instance()
        if application is not None:
            color_scheme = application.styleHints().colorScheme()
            if color_scheme.name.lower() == DARK:
                return DARK
            if color_scheme.name.lower() == LIGHT:
                return LIGHT

    return DEFAULT_THEME


def palette(theme: str = DEFAULT_THEME) -> dict[str, str]:
    """پالت تم داده‌شده را برمی‌گرداند؛ تم سیستم از Qt حل می‌شود."""
    return dict(LIGHT_PALETTE if effective_theme(theme) == LIGHT else DARK_PALETTE)


def normalise_theme(value: str | None) -> str:
    """مقدار ذخیره‌شده تم را به یکی از تم‌های شناخته‌شده تبدیل می‌کند."""
    normalised = (value or "").strip().lower()
    return normalised if normalised in THEMES else DARK


def stylesheet(theme: str = DEFAULT_THEME) -> str:
    """استایل کامل برنامه را برای تم داده‌شده می‌سازد.

    جایگزینی با مرز واژه انجام می‌شود تا توکن‌هایی که اولشان یکی است
    (مثل `@accent` و `@accentSoft`) همدیگر را خراب نکنند.
    """
    colors = palette(theme)
    output = STYLESHEET_TEMPLATE
    for token, hex_value in colors.items():
        output = re.sub("@" + token + r"(?![A-Za-z0-9_])", hex_value, output)
    output += f"""
            #conversationButton:hover,
            #navigationButton:hover,
            #bubbleCopyButton:hover,
            #ghostButton:hover,
            #themeToggle:hover {{
                color: {colors['textPrimary']};
            }}
        """
    output += f"""
            #settingsFieldLabel {{
                color: {colors['textPrimary']};
            }}
            #helpPage, #helpTabContent {{
                background-color: {colors['window']};
            }}
        """
    leftover = re.findall(r"@[A-Za-z_][A-Za-z0-9_]*", output)
    if leftover:  # pragma: no cover - محافظ نگهداری، نه مسیر عادی
        raise ValueError("توکن‌های بدون مقدار در پالت: " + ", ".join(leftover))
    return output


